function createWorkspaceCommand(config) {
  const { logger, sessionManager, withSupabaseClient, webAppUrl, loginCommand, workspaceCommand } = config;
  function showWorkspaces(workspaces, session) {
    if (session.workspaceId && session.workspaceName) {
      console.log(`Current: ${session.workspaceName}`);
      console.log("");
    }
    console.log("Available workspaces:");
    for (const [i, ws] of workspaces.entries()) {
      const marker = session.workspaceId === ws.id ? "✓" : " ";
      console.log(`${marker} ${i + 1}. ${ws.name}`);
    }
    console.log("");
    console.log(`Switch: ${workspaceCommand} {number}`);
  }
  return async (args = []) => {
    try {
      const session = await sessionManager.loadSession();
      if (!session) {
        console.log(`❌ Not authenticated — run ${loginCommand} first`);
        return;
      }
      const workspaces = await withSupabaseClient((supabase) => fetchUserWorkspaces(supabase, session.userId, { logger }));
      if (!workspaces) {
        console.log("❌ Failed to fetch workspaces — authentication may have expired");
        console.log(`   Run ${loginCommand} to re-authenticate`);
        return;
      }
      if (workspaces.length === 0) {
        console.log("❌ No workspaces found");
        console.log(`   Create one at: ${webAppUrl}/onboarding`);
        return;
      }
      workspaces.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
      const freshName = await sessionManager.reconcileWorkspaceName(session, workspaces);
      const displaySession = freshName !== session.workspaceName ? { ...session, workspaceName: freshName } : session;
      if (args.length === 0) {
        showWorkspaces(workspaces, displaySession);
        return;
      }
      const selectedWorkspace = findWorkspace(workspaces, args[0]);
      if (!selectedWorkspace) {
        console.log("❌ Workspace not found");
        console.log(`   Run ${workspaceCommand} to see available workspaces`);
        process.exit(1);
        return;
      }
      await sessionManager.updateWorkspaceInSession(selectedWorkspace.id, selectedWorkspace.name);
      console.log(`✅ Switched to: ${selectedWorkspace.name}`);
    } catch (error) {
      logger.error("Workspace command failed", error);
      console.error("❌ Failed to manage workspace");
      if (error instanceof Error)
        console.error(`   ${error.message}`);
      process.exit(1);
    }
  };
}
